import dao.*;import model.*;import java.sql.*;import java.nio.file.*;import java.time.*;
public class Smoke5{static void check(boolean x,String s){if(!x)throw new AssertionError(s);System.out.println("PASS "+s);}public static void main(String[] args)throws Exception{Class.forName("org.h2.Driver");try(Connection c=DriverManager.getConnection("jdbc:h2:mem:cinema;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1")){String sql=Files.readString(Path.of(args[0]));for(String q:sql.split(";")){if(q.contains("CREATE TABLE"))c.createStatement().execute(q);}c.createStatement().execute("INSERT INTO tblMember5(id,Username,Password,HoVaTen) VALUES(1,'khach','x','Khách')");c.createStatement().execute("INSERT INTO tblCustomer5 VALUES(1,'KH01')");c.createStatement().execute("INSERT INTO tblCinema5(id,MaRap) VALUES(1,1)");c.createStatement().execute("INSERT INTO tblScreeningRoom5(id,MaPhong,tblCinema5id) VALUES(1,'P01',1)");c.createStatement().execute("INSERT INTO tblSeat5(id,MaGhe,LoaiGhe,tblScreeningRoom5id) VALUES(1,'E5','VIP',1),(2,'E6','VIP',1)");Movie5 m=new Movie5();m.setTenPhim("Phim thử");m.setTacGia("Tác giả");m.setThoiLuong(128);m.setTheLoai("Hành động");new MovieDAO5(c).saveMovie(m);check(new MovieDAO5(c).get(m.getId()).getTenPhim().equals("Phim thử"),"lưu/đọc đủ thuộc tính phim");try(PreparedStatement p=c.prepareStatement("INSERT INTO tblScreening5(id,GioBatDau,GioKetThuc,TrangThai,tblMovie5id,tblScreeningRoom5id) VALUES(1,?,?,'MO_BAN',?,1)")){p.setObject(1,LocalDateTime.now().plusDays(1));p.setObject(2,LocalDateTime.now().plusDays(1).plusHours(2));p.setInt(3,m.getId());p.executeUpdate();}Customer5 customer=new MemberDAO5(c).customer(1);Screening5 s=new ScreeningDAO5(c).get(1);Seat5[] seats=new SeatDAO5(c).getSeats(s);Ticket5[] ts=new TicketDAO5(c).prepareTickets(s,seats);Order5 o=new OrderDAO5(c).createOrder(customer,ts,null);check(o.getTongTien().intValue()==150000,"tổng tiền 2 ghế VIP");try{new Checkout5(c).complete(o,"THU_THAT_BAI");throw new AssertionError();}catch(IllegalArgumentException ok){}check(new TicketDAO5(c).getBookedTickets(s).length==0,"thanh toán thất bại không phát hành vé");Order5 paid=new Checkout5(c).complete(o,"THE");check(paid.getMaHoaDon()!=null&&paid.getVe().length==2,"hóa đơn gộp Order5 và phát hành 2 vé");check(paid.getVe()[0].getSuatChieu().getPhim().getTenPhim().equals("Phim thử"),"tham chiếu vé -> suất -> phim");check(paid.getThanhToan().length==2,"đọc lại cả hai lần thanh toán");check(new Checkout5(c).complete(o,"THE").getVe().length==2,"gửi lại không bán vé lần hai");try{new TicketDAO5(c).prepareTickets(s,seats);throw new AssertionError();}catch(IllegalArgumentException ok){check(true,"chặn ghế đã bán");}check(new CinemaDAO5(c).getCinemas()[0].getListPhongChieu()[0].getListGhe().length==2,"rạp -> phòng -> ghế");}}
}
